key.query:
query GetCategoryBanner($id: ID!) {
  category(id: $id, idType: DATABASE_ID) {
    affiliatedBanner {
      bannerType
      bannerHeadline
      bannerSubtext
      bannerCtaLabel
      bannerCtaUrl
      openInNewTab
      bannerEnabled
      bannerImage {
        node {
          sourceUrl
          altText
          mediaDetails {
            sizes {
              name
              sourceUrl
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
